const D=window.PROTOCOLS_DATA;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const ALL=['reconstructed','K','A1','A2','N','B'], WITS=['K','A1','A2','N','B'];
const TYPE_LABEL={persons:'Person',places:'Place',organizations:'Organization',works:'Work'};
const esc=s=>(s??'').toString().replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const styleFor=w=>D.witnessStyles?.[w]||{label:w,color:'#555',short:w};
const witnessLabel=w=>styleFor(w).label||w;
function parseRoute(){const raw=(location.hash||'#home').slice(1),[page,qs='']=raw.split('?');return {page:page||'home',p:new URLSearchParams(qs)}}
function go(page,params={}){const q=new URLSearchParams();Object.entries(params).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')q.set(k,v)});location.hash=page+(q.toString()?'?'+q:'')}
function routeLink(page,params,label,cls=''){const q=new URLSearchParams();Object.entries(params||{}).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')q.set(k,v)});return `<a class="${cls}" href="#${page}${q.toString()?'?'+q:''}">${label}</a>`}
function norm(s){return (s||'').toLowerCase().replace(/ё/g,'е').replace(/[^а-яa-z0-9]+/gi,' ').trim()}
function romanLabel(s){return s?.type==='protocol'?'Protocol '+s.label:(s?.label||'')}
function cssVar(w){return `style="--wit:${styleFor(w).color}"`}
function witnessPill(w,label=witnessLabel(w)){return `<span class="wit-pill" ${cssVar(w)}><i></i>${esc(label)}</span>`}
function clamp(n,a,b){return Math.max(a,Math.min(b,n))}
function entityById(id){for(const [typ,arr] of Object.entries(D.entities)){const e=arr.find(x=>x.id===id);if(e)return {typ,e}}}
function conceptById(id){return D.conceptIndex?.concepts?.find(x=>x.id===id)}

// ---------- shared entity markup ----------
const ENTITY_FORMS=[];
Object.entries(D.entities).forEach(([typ,arr])=>arr.forEach(e=>(e.forms||[]).forEach(f=>ENTITY_FORMS.push({f,typ,id:e.id,label:e.label}))));
ENTITY_FORMS.sort((a,b)=>b.f.length-a.f.length);
function markupText(text,q='',entitiesOn=true){
  if(!text)return '';
  if(!entitiesOn){let h=esc(text);if(q&&q.length>1){const rq=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');h=h.replace(rq,m=>`<mark>${m}</mark>`)}return h.replace(/\n/g,'<br>')}
  const hits=[];
  for(const e of ENTITY_FORMS){const re=new RegExp(`(^|[^А-Яа-яЁёA-Za-z])(${e.f.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})(?=$|[^А-Яа-яЁёA-Za-z])`,'gi');let m;while((m=re.exec(text))){const st=m.index+m[1].length,en=st+m[2].length;if(!hits.some(h=>!(en<=h.st||st>=h.en)))hits.push({st,en,e});if(re.lastIndex===m.index)re.lastIndex++}}
  hits.sort((a,b)=>a.st-b.st);let out='',pos=0;
  function plain(s){let h=esc(s);if(q&&q.length>1){const rq=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');h=h.replace(rq,m=>`<mark>${m}</mark>`)}return h}
  for(const h of hits){out+=plain(text.slice(pos,h.st));out+=`<a class="entity-mention ${h.e.typ}" href="#entities?entity=${encodeURIComponent(h.e.id)}" title="${esc(h.e.label)}">${esc(text.slice(h.st,h.en))}</a>`;pos=h.en}
  out+=plain(text.slice(pos));return out.replace(/\n/g,'<br>')
}

// ---------- word alignment for synopsis ----------
function wtokens(text){return (text||'').trim().split(/\s+/).filter(Boolean)}
function tokenKey(t){return norm(t)}
function alignWords(base,other){
  const A=wtokens(base),B=wtokens(other),n=A.length,m=B.length;
  if(!n&&!m)return {ops:[],A,B,matched:new Set()};
  // For exceptionally long spans, fall back to set comparison to keep the UI responsive.
  if(n*m>2200000){
    const aset=new Set(A.map(tokenKey));const matched=new Set();const ops=[];
    B.forEach((t,j)=>{if(aset.has(tokenKey(t)))ops.push({t:'eq',b:j,text:t});else ops.push({t:'ins',b:j,text:t})});
    A.forEach((t,i)=>{if(B.some(x=>tokenKey(x)===tokenKey(t)))matched.add(i)});
    return {ops,A,B,matched,fallback:true};
  }
  const rows=Array.from({length:n+1},()=>new Uint16Array(m+1));
  for(let i=1;i<=n;i++)for(let j=1;j<=m;j++)rows[i][j]=tokenKey(A[i-1])===tokenKey(B[j-1])?rows[i-1][j-1]+1:Math.max(rows[i-1][j],rows[i][j-1]);
  let i=n,j=m,ops=[],matched=new Set();
  while(i>0||j>0){
    if(i>0&&j>0&&tokenKey(A[i-1])===tokenKey(B[j-1])){ops.push({t:'eq',a:i-1,b:j-1,text:B[j-1]});matched.add(i-1);i--;j--}
    else if(j>0&&(i===0||rows[i][j-1]>=rows[i-1][j])){ops.push({t:'ins',b:j-1,text:B[j-1]});j--}
    else{ops.push({t:'del',a:i-1,text:A[i-1]});i--}
  }
  return {ops:ops.reverse(),A,B,matched}
}
function renderDiffOps(al){
  let out='',i=0;const ops=al.ops;
  while(i<ops.length){
    if(ops[i].t==='eq'){out+=` ${esc(ops[i].text)}`;i++;continue}
    const group=[];while(i<ops.length&&ops[i].t!=='eq'){group.push(ops[i]);i++}
    const ins=group.filter(x=>x.t==='ins'),del=group.filter(x=>x.t==='del');
    if(ins.length&&del.length){out+=` <span class="diff-sub" title="Replaces: ${esc(del.map(x=>x.text).join(' '))}">${ins.map(x=>esc(x.text)).join(' ')}</span>`}
    else if(ins.length){out+=` <span class="diff-add">${ins.map(x=>esc(x.text)).join(' ')}</span>`}
    else if(del.length){out+=` <span class="diff-gap" title="Absent here: ${esc(del.map(x=>x.text).join(' '))}">−${del.length}</span>`}
  }
  return out.trim();
}
function renderReference(base,alignments){
  const A=wtokens(base),counts=new Array(A.length).fill(0);
  alignments.forEach(al=>{for(let i=0;i<A.length;i++)if(!al.matched.has(i))counts[i]++});
  return A.map((t,i)=>counts[i]?`<span class="diff-base" style="--d:${counts[i]/Math.max(1,alignments.length)}" title="Differs in ${counts[i]} visible witness${counts[i]===1?'':'es'}">${esc(t)}</span>`:esc(t)).join(' ')
}

// ---------- live transmission map ----------
const MAP_NODES={W:[420,42,true],K:[95,145,false],R:[742,145,false],Z:[420,140,true],X:[270,245,true],Y:[560,245,true],A1:[160,345,false],B:[355,345,false],A2:[500,345,false],N:[650,345,false],I:[770,345,false]};
const MAP_EDGES=[['W','K','descent'],['W','R','descent'],['W','Z','descent'],['Z','X','descent'],['Z','Y','descent'],['X','A1','descent'],['X','B','descent'],['Y','A2','descent'],['Y','N','descent'],['N','I','descent'],['B','Y','contamination']];
function branchDesc(id){return {W:['K','A1','B','A2','N'],Z:['A1','B','A2','N'],X:['A1','B'],Y:['A2','N'],R:[],I:[]}[id]||([id].filter(x=>WITS.includes(x)))}
function liveMap(compact=false){
  const edges=MAP_EDGES.map(([a,b,k])=>{const A=MAP_NODES[a],B=MAP_NODES[b];return `<line class="tm-edge ${k}" x1="${A[0]}" y1="${A[1]}" x2="${B[0]}" y2="${B[1]}" data-from="${a}" data-to="${b}"/>`}).join('');
  const nodes=Object.entries(MAP_NODES).map(([id,v])=>{const ext=WITS.includes(id),col=ext?styleFor(id).color:'#69747b';return `<g class="tm-node ${v[2]?'hyp':''} ${ext?'extant':''}" data-node="${id}" tabindex="0" style="--node:${col}"><circle cx="${v[0]}" cy="${v[1]}" r="25"/><text x="${v[0]}" y="${v[1]}">${id}</text></g>`}).join('');
  return `<div class="transmission ${compact?'compact':''}"><svg viewBox="0 0 850 395" role="img" aria-label="Interactive transmission map">${edges}${nodes}</svg><div class="tm-inspector" id="tmInspector"><div class="kicker">Transmission map</div><b>Select a node</b><p>Hover to trace relationships. Select a surviving witness to read it; select a hypothetical stage to compare its descendants.</p></div></div>`
}
function setupMap(){
  $$('.tm-node').forEach(g=>{const id=g.dataset.node;const activate=()=>{if(WITS.includes(id))go('edition',{wit:id,unit:1});else{const cols=branchDesc(id);if(cols.length)go('synopsis',{basis:cols[0],unit:1,cols:cols.join(',')})}};g.onclick=activate;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')activate()};g.onmouseenter=()=>{
    $$('.tm-edge').forEach(e=>e.classList.toggle('hot',e.dataset.from===id||e.dataset.to===id));$$('.tm-node').forEach(n=>n.classList.toggle('dim',n.dataset.node!==id&&!MAP_EDGES.some(e=>(e[0]===id&&e[1]===n.dataset.node)||(e[1]===id&&e[0]===n.dataset.node))));
    const descendants=branchDesc(id);const meta=D.project.witnesses.find(x=>x.id===id);$('#tmInspector').innerHTML=meta?`<div class="kicker">${meta.redaction}</div><b>${id} · ${meta.date}</b><p>${esc(meta.description)}</p><span class="inline-action">Open witness →</span>`:`<div class="kicker">Hypothetical stage</div><b>${id}</b><p>${descendants.length?`Surviving descendants represented here: ${descendants.join(', ')}.`:'No continuous surviving witness in this edition.'}</p>${descendants.length?'<span class="inline-action">Compare descendants →</span>':''}`;
  };g.onmouseleave=()=>{$$('.tm-edge').forEach(e=>e.classList.remove('hot'));$$('.tm-node').forEach(n=>n.classList.remove('dim'))}})
}

// ---------- structural ribbons and variance landscape ----------
function structuralRibbon(){
  const rows=Object.entries(D.project.segmentation).map(([k,a])=>`<div class="sr-row"><div class="sr-label">${esc(k)}</div><div class="sr-track">${a.map((x,i)=>`<button class="sr-seg" style="left:${x.left}%;width:${x.width}%" data-basis="${k}" data-i="${i}" title="${k} · Protocol ${x.label}"><span>${x.label}</span></button>`).join('')}</div></div>`).join('');
  return `<div class="structural-ribbon">${rows}</div>`
}
function setupRibbon(){$$('.sr-seg').forEach(b=>b.onclick=()=>{let basis=b.dataset.basis.startsWith('A1')?'A1':b.dataset.basis.startsWith('A2')?'A2':b.dataset.basis;go('synopsis',{basis,unit:+b.dataset.i+1,cols:'K,A1,A2,N,B'})})}
function varianceLandscape(){const max=Math.max(...D.varianceLandscape.map(x=>x.mean),.01);return `<div class="variance-strip">${D.varianceLandscape.map(x=>`<button class="var-cell" style="--v:${x.mean/max}" data-unit="${x.unit_index}" title="Protocol ${x.label}: mean normalized variation ${(x.mean*100).toFixed(1)}%"><span>${x.label}</span><i></i></button>`).join('')}</div>`}
function setupVariance(){$$('.var-cell').forEach(b=>b.onclick=()=>go('synopsis',{basis:'reconstructed',unit:b.dataset.unit,cols:'K,A1,A2,N,B'}))}


// ---------- entity atlas: witness profiles + named-entity types ----------
function entityAtlas(compact=false){
  const rows=D.nerIndex.matrix.slice().sort((a,b)=>{
    const ta=Object.values(a.counts||{}).reduce((x,y)=>x+y,0),tb=Object.values(b.counts||{}).reduce((x,y)=>x+y,0);return tb-ta
  }).slice(0,compact?22:36);
  const order=['K','A1','B','A2','N'], x0=100, step=175, width=900, height=compact?360:500;
  const yBand={persons:compact?150:190,places:compact?215:285,organizations:compact?280:380,works:compact?330:455};
  const totals=rows.map(r=>Object.values(r.counts||{}).reduce((a,b)=>a+b,0)), max=Math.max(...totals,1);
  const typeIndex={persons:0,places:1,organizations:2,works:3};
  const nodeHtml=rows.map((r,ri)=>{
    const counts=order.map(w=>r.counts?.[w]||0),sum=counts.reduce((a,b)=>a+b,0)||1;
    let wx=counts.reduce((a,n,i)=>a+n*i,0)/sum;
    const jitter=((ri*37)%17-8)*2.2;
    const x=x0+wx*step+jitter, y=(yBand[r.type]||250)+(((ri*23)%13)-6)*(compact?2.6:4);
    const total=totals[ri], rad=(compact?5:6)+(compact?7:11)*Math.sqrt(total/max);
    const showLabel=!compact&&(total>=10||r.spread>=5);const side=ri%2?1:-1, lx=x+side*(rad+5), ly=y+(((ri%3)-1)*8)+3;return `<g class="atlas-entity ${r.type}" data-entity="${r.id}" onclick="go('entities',{entity:'${r.id}'})" tabindex="0"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${rad.toFixed(1)}"/><title>${esc(r.label)} · ${total} mentions · spread ${r.spread}</title>${showLabel?`<text class="atlas-label ${side<0?'left':'right'}" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}">${esc(r.label.length>24?r.label.slice(0,22)+'…':r.label)}</text>`:''}</g>`
  }).join('');
  const guides=order.map((w,i)=>{const x=x0+i*step;return `<g class="atlas-witness" ${cssVar(w)} onclick="go('edition',{wit:'${w}',unit:1})" tabindex="0"><line x1="${x}" y1="52" x2="${x}" y2="${height-24}"/><circle cx="${x}" cy="42" r="13"/><text x="${x}" y="46">${w}</text></g>`}).join('');
  const bands=compact?'':Object.entries(yBand).map(([t,y])=>`<text class="atlas-band-label" x="10" y="${y+4}">${TYPE_LABEL[t]||t}</text>`).join('');
  return `<div class="entity-atlas-wrap"><svg class="entity-atlas ${compact?'compact':''}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Entity atlas by witness profile and entity type">${guides}${bands}${nodeHtml}</svg><div class="atlas-legend"><span><i class="type-dot persons"></i>people</span><span><i class="type-dot places"></i>places</span><span><i class="type-dot organizations"></i>organizations</span><span><i class="type-dot works"></i>works</span><small>Horizontal position = weighted witness profile; node size = total mentions. Select any entity to open its index.</small></div></div>`
}

// ---------- HOME ----------
function witnessCards(){return D.project.witnesses.map(w=>`<article class="wcard" ${cssVar(w.id)}><div class="wcard-rule"></div><div class="wcard-top"><div>${witnessPill(w.id,w.id)}<h3>${w.date}</h3></div><span class="parts">${w.parts} parts</span></div><div class="meta-line">${esc(w.redaction)}</div><p>${esc(w.description)}</p><div class="card-actions">${routeLink('edition',{wit:w.id,unit:1},'Read','btn btn-small')}${routeLink('synopsis',{basis:w.id,unit:1,cols:'K,A1,A2,N,B'},'Compare','link-arrow')}</div></article>`).join('')}
function home(){setTimeout(()=>{setupMap();setupRibbon();setupVariance()},0);return `
<div class="internal-notice"><b>Experimental research version</b><span>Internal use only · working reconstruction for scholarly review.</span></div>
<section class="hero-v7">
  <div class="hero-copy"><div class="kicker">Digital critical edition · multi-witness research environment</div><h1>${esc(D.project.title.replace(' — Digital Critical Reconstruction',''))}</h1><p class="hero-sub">The edition is designed as a navigable field rather than a sequence of tabs: witness structure, textual variance, entities, and transmission all lead into the same passages.</p>
  <div class="hero-actions">${routeLink('edition',{wit:'reconstructed',unit:1},'Read the edition','btn btn-primary')}${routeLink('synopsis',{basis:'K',unit:1,cols:'K,A1,A2,N,B'},'Open comparative view','btn btn-quiet')}${routeLink('distant',{},'Distant reading','btn btn-quiet')}</div>
  <div class="metric-row"><div><b>${D.project.counts.apparatus_notes.toLocaleString()}</b><span>apparatus loci</span></div><div><b>${D.nerMeta.occurrences.toLocaleString()}</b><span>NER mentions</span></div><div><b>22 / 27 / 24</b><span>competing organizations</span></div></div></div>
  <div class="hero-map card">${liveMap(true)}</div>
</section>
<section class="home-section"><div class="section-heading"><div><div class="kicker">Navigate by variation</div><h2>A landscape of textual change</h2></div><p>Each cell is one protocol in the reconstructed 22-part sequence. Darkness reflects average difference across K, A1, A2, N, and B; select a cell to compare that locus.</p></div>${varianceLandscape()}</section>
<section class="home-grid-v7"><div class="card"><div class="kicker">Competing structures</div><h2>One continuum, three organizations</h2><p class="muted">The same textual continuum is partitioned differently. These boundaries are live and remain visible inside the reader and synopsis.</p>${structuralRibbon()}</div><div class="card route-card"><div class="kicker">Three ways in</div><div class="route-list">${routeLink('edition',{wit:'K',unit:1},'<b>Close reading</b><span>Read one witness with protocol anatomy, apparatus, entities, and cross-witness boundaries.</span>')}${routeLink('synopsis',{basis:'A1',unit:1,cols:'K,A1,A2,N,B'},'<b>Comparison</b><span>Choose, remove, and reorder witnesses; change the organizing structure without flattening it.</span>')}${routeLink('distant',{},'<b>Distant reading</b><span>Move through entity geography, co-occurrence networks, concept profiles, and witness differences.</span>')}</div></div></section>
<section class="home-section"><div class="section-heading"><div><div class="kicker">Distant reading · entity atlas</div><h2>Where named entities cluster across the witnesses</h2></div><p>This map places entities by their weighted witness profile and entity type. Node size reflects total mentions. Every node leads back to its indexed occurrences.</p></div><div class="card home-atlas">${entityAtlas(true)}<div class="card-actions atlas-actions">${routeLink('distant',{view:'atlas'},'Open full entity atlas →','link-arrow')}${routeLink('entities',{},'Browse the entity index','link-arrow')}</div></div></section>
<section class="home-section"><div class="section-heading"><div><div class="kicker">Surviving witnesses</div><h2>Witnesses are persistent identities</h2></div><p>Each witness keeps the same color throughout the site, but color is always paired with a label.</p></div><div class="wgrid-v7">${witnessCards()}</div></section>`}

// ---------- EDITION / CLOSE READING ----------
function anatomyBar(wit,unit){const a=D.anatomy?.[wit]?.[unit];if(!a||!a.blocks?.length)return '';const total=a.blocks.reduce((s,b)=>s+Math.max(1,b.word_count),0),mx=Math.max(1,...a.blocks.map(b=>b.variant_count));return `<div class="anatomy-bar" aria-label="Internal protocol map">${a.blocks.map(b=>`<button data-block="${b.index}" style="flex:${Math.max(1,b.word_count)};--heat:${b.variant_count/mx}" title="${esc(b.label)} · ${b.word_count} words · ${b.variant_count} variant operations"><span>${esc(b.label)}</span></button>`).join('')}</div>`}
function renderProtocolBlocks(wit,unit,text,q='',entitiesOn=true){const a=D.anatomy?.[wit]?.[unit];if(!a||!a.blocks?.length)return markupText(text,q,entitiesOn);return a.blocks.map(b=>{const chunk=text.slice(b.start,b.end);const top=b.concepts.map(c=>conceptById(c.id)?.label).filter(Boolean).slice(0,2);return `<section class="protocol-block" id="block-${b.index}" data-block="${b.index}"><div class="block-margin"><span class="block-code">${esc(b.label)}</span><span class="block-var" title="${b.variant_count} witness operations">${b.variant_count}</span></div><div class="block-body">${top.length?`<div class="block-tags">${top.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div>${markupText(chunk,q,entitiesOn)}</div></div></section>`}).join('')}
function edition(){setTimeout(setupEdition,0);return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Close reading</div><h1>Edition</h1></div><div class="page-actions"><a class="btn btn-quiet" href="${D.teiDownloads.package}" download>TEI package ↓</a></div></div><div id="readerControls" class="reader-controls card"></div><div class="reader-layout"><aside class="reader-nav card"><div class="side-title">Structure</div><div id="unitList"></div></aside><main class="reading-card card"><div id="readingHeader"></div><div id="readingText" class="reading-text"></div></main><aside class="reader-inspector card"><div class="inspector-tabs"><button data-tab="anatomy" class="active">Anatomy</button><button data-tab="apparatus">Apparatus</button><button data-tab="entities">Entities</button></div><div id="inspectorBody"></div></aside></div></div>`}
function setupEdition(){
 const R=parseRoute();let wit=R.p.get('wit')||'reconstructed';if(!ALL.includes(wit))wit='reconstructed';let unit=+(R.p.get('unit')||1);let entitiesOn=R.p.get('entities')!=='0';let inspect='anatomy';
 const control=$('#readerControls');
 function segs(){return wit==='reconstructed'?D.reconstructed:D.witnesses[wit]}
 function normalizeUnit(){const ss=segs();if(unit<0||unit>=ss.length)unit=ss.findIndex(s=>s.type==='protocol');if(unit<0)unit=0}
 function sync(){history.replaceState(null,'',`#edition?wit=${wit}&unit=${unit}&entities=${entitiesOn?1:0}`)}
 function drawControls(){control.innerHTML=`<div class="control-group witness-switch"><span class="control-label">Text</span>${ALL.map(w=>`<button class="witness-btn ${w===wit?'active':''}" data-w="${w}" ${cssVar(w)}><i></i>${esc(styleFor(w).short)}</button>`).join('')}</div><div class="control-divider"></div><div class="control-group"><button id="prevUnit" class="icon-btn" title="Previous unit">←</button><select id="unitSelect">${segs().map((s,i)=>`<option value="${i}" ${i===unit?'selected':''}>${esc(romanLabel(s))}</option>`).join('')}</select><button id="nextUnit" class="icon-btn" title="Next unit">→</button></div><div class="control-spacer"></div><label class="toggle"><input id="entityToggle" type="checkbox" ${entitiesOn?'checked':''}><span></span> Entities</label><button id="compareUnit" class="btn btn-small">Compare this locus</button><a class="btn btn-small btn-quiet" href="${wit==='reconstructed'?D.teiDownloads.edition:D.teiDownloads[wit]}" download>TEI ↓</a>`;
  $$('.witness-btn').forEach(b=>b.onclick=()=>{wit=b.dataset.w;unit=Math.min(unit,segs().length-1);normalizeUnit();sync();drawAll()});$('#unitSelect').onchange=e=>{unit=+e.target.value;sync();drawAll()};$('#prevUnit').onclick=()=>{unit=Math.max(0,unit-1);sync();drawAll()};$('#nextUnit').onclick=()=>{unit=Math.min(segs().length-1,unit+1);sync();drawAll()};$('#entityToggle').onchange=e=>{entitiesOn=e.target.checked;sync();drawReader()};$('#compareUnit').onclick=()=>go('synopsis',{basis:wit,unit,cols:'K,A1,A2,N,B'});
 }
 function drawNav(){const ss=segs();$('#unitList').innerHTML=ss.map((s,i)=>{const a=D.anatomy?.[wit]?.[i];return `<button class="unit-nav ${i===unit?'active':''}" data-i="${i}" ${cssVar(wit)}><span>${esc(romanLabel(s))}</span>${a?`<small>${a.blocks.length} blocks · ${a.variant_count} variants</small>`:''}</button>`}).join('');$$('.unit-nav').forEach(b=>b.onclick=()=>{unit=+b.dataset.i;sync();drawAll()})}
 function drawReader(){const s=segs()[unit],a=D.anatomy?.[wit]?.[unit];$('#readingHeader').innerHTML=`<div class="reading-meta"><div>${witnessPill(wit)}<div class="reading-kicker">${esc(romanLabel(s))}</div></div><div class="reading-stats">${a?`<span>${a.word_count} words</span><span>${a.blocks.length} internal blocks</span><span>${a.variant_count} witness operations</span>`:''}</div></div>${anatomyBar(wit,unit)}`;$('#readingText').innerHTML=renderProtocolBlocks(wit,unit,s.text,R.p.get('q')||'',entitiesOn);$$('.anatomy-bar button').forEach(b=>b.onclick=()=>{$(`#block-${b.dataset.block}`)?.scrollIntoView({behavior:'smooth',block:'center'});showBlock(+b.dataset.block)});$$('.protocol-block').forEach(b=>b.onclick=e=>{if(e.target.closest('a'))return;showBlock(+b.dataset.block)})}
 function showBlock(ix){inspect='anatomy';$$('.inspector-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='anatomy'));drawInspector(ix)}
 function drawInspector(selectedBlock=0){const s=segs()[unit],a=D.anatomy?.[wit]?.[unit];const body=$('#inspectorBody');if(inspect==='anatomy'){
    if(!a){body.innerHTML='<p class="muted">No structural map for this unit.</p>';return}const b=a.blocks[clamp(selectedBlock,0,a.blocks.length-1)];const ent=b.entity_ids.map(id=>entityById(id)).filter(Boolean);body.innerHTML=`<div class="inspector-section"><div class="kicker">Protocol anatomy</div><h3>${esc(romanLabel(s))}</h3><p class="muted">Blocks are delimited by De Michelis’s Joly-source loci where available; otherwise by neutral sentence groups. This is a textual map, not a semantic paraphrase.</p></div><div class="block-detail"><span class="big-code">${esc(b.label)}</span><div><b>${b.word_count} words</b><p>${esc(b.incipit)}…</p></div></div><div class="mini-metrics"><span><b>${b.variant_count}</b> witness operations</span><span><b>${b.entity_ids.length}</b> indexed entities</span></div>${b.concepts.length?`<div class="inspector-section"><div class="side-title">Dominant indexed concepts</div><div class="chips">${b.concepts.map(c=>`<button class="chip" data-concept="${c.id}">${esc(conceptById(c.id)?.label||c.id)} <small>${c.count}</small></button>`).join('')}</div></div>`:''}${ent.length?`<div class="inspector-section"><div class="side-title">Entities in this block</div><div class="chips">${ent.map(x=>routeLink('entities',{entity:x.e.id},esc(x.e.label),'chip')).join('')}</div></div>`:''}<div class="inspector-section"><div class="side-title">Other witness boundaries inside this unit</div>${a.boundaries.length?`<div class="boundary-list">${a.boundaries.map(x=>`<button onclick="go('synopsis',{basis:'${x.witness}',unit:0,cols:'K,A1,A2,N,B'})">${witnessPill(x.witness,x.witness)} <span>Protocol ${esc(x.label)} begins at ${(x.position*100).toFixed(0)}%</span></button>`).join('')}</div>`:'<p class="muted">No other encoded witness boundary falls inside this unit.</p>'}</div>`;
  }else if(inspect==='apparatus'){
    const st=s.start_note||0;const next=segs()[unit+1]?.start_note||99999;const notes=D.apparatus.filter(o=>o.note>=st&&o.note<next&&(wit==='reconstructed'||o.witness===wit));body.innerHTML=`<div class="kicker">Critical apparatus</div><h3>${notes.length} operations in this unit</h3><div class="apparatus-list">${notes.slice(0,250).map(o=>`<article><b>${o.witness} · ${o.action}</b><span>note ${o.note}</span><p>${esc(o.lemma_candidate||'∅')} <i>→</i> ${esc(o.reading_candidate||'∅')}</p></article>`).join('')||'<p class="muted">No operations recorded here.</p>'}</div>`;
  }else{
    const os=D.nerIndex.occurrences.filter(o=>o.witness===wit&&o.unit_index===unit);const by=CounterJS(os.map(o=>o.entity));body.innerHTML=`<div class="kicker">Named entities</div><h3>${os.length} mentions</h3><div class="entity-mini-list">${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([id,n])=>{const x=entityById(id);return x?routeLink('entities',{entity:id},`<span>${esc(x.e.label)}</span><b>${n}</b>`,'entity-mini'):''}).join('')||'<p class="muted">No named entities indexed in this unit.</p>'}</div>`
  }}
 function drawAll(){normalizeUnit();drawControls();drawNav();drawReader();drawInspector(0);$$('.inspector-tabs button').forEach(b=>b.onclick=()=>{inspect=b.dataset.tab;$$('.inspector-tabs button').forEach(x=>x.classList.toggle('active',x===b));drawInspector(0)})}
 drawAll();
}
function CounterJS(arr){const o={};arr.forEach(x=>o[x]=(o[x]||0)+1);return o}

// ---------- SYNOPSIS ----------
function synopsis(){setTimeout(setupSynopsis,0);return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Comparative reading</div><h1>Synopsis</h1><p>Choose the organizing structure independently from the witnesses you display. Drag witness chips to reorder; the first visible witness is the textual reference for highlighting.</p></div></div><div id="synControls" class="syn-controls-v7 card"></div><div id="synSummary" class="syn-summary"></div><div id="syn" class="synopsis-v7"></div></div>`}
function setupSynopsis(){
 const R=parseRoute();let basis=R.p.get('basis')||'K';if(!D.synopsisByBasis[basis])basis='K';let unit=+(R.p.get('unit')||1);let cols=(R.p.get('cols')||'K,A1,A2,N,B').split(',').filter(x=>WITS.includes(x));if(cols.length<2)cols=['K','A1'];let diff=true;
 const controls=$('#synControls');
 function sync(){history.replaceState(null,'',`#synopsis?basis=${basis}&unit=${unit}&cols=${cols.join(',')}`)}
 function rows(){return D.synopsisByBasis[basis]}
 function drawControls(){const hidden=WITS.filter(x=>!cols.includes(x));controls.innerHTML=`<div class="syn-line"><label><span class="control-label">Organize by</span><select id="basisSel">${ALL.map(w=>`<option value="${w}" ${w===basis?'selected':''}>${esc(witnessLabel(w))}</option>`).join('')}</select></label><label><span class="control-label">Unit</span><select id="synUnit">${rows().map((u,i)=>`<option value="${i}" ${i===unit?'selected':''}>${esc(romanLabel(u))}</option>`).join('')}</select></label><div class="control-spacer"></div><label class="toggle"><input id="diffToggle" type="checkbox" ${diff?'checked':''}><span></span> Highlight variants</label></div><div class="witness-tray"><div><span class="control-label">Visible witnesses · drag to reorder</span><div id="activeWits" class="active-wits">${cols.map(w=>`<button draggable="true" class="drag-wit" data-w="${w}" ${cssVar(w)}><i></i><b>⋮⋮</b>${w}<span data-remove="${w}">×</span></button>`).join('')}</div></div><div><span class="control-label">Add witness</span><div class="add-wits">${hidden.map(w=>`<button data-add="${w}" ${cssVar(w)}><i></i>+ ${w}</button>`).join('')||'<span class="muted">All witnesses shown</span>'}</div></div></div><div class="diff-legend"><span><i class="legend-sub"></i> substitution</span><span><i class="legend-add"></i> addition</span><span><i class="legend-gap"></i> omission</span><span><i class="legend-struct"></i> structural boundary</span></div>`;
   $('#basisSel').onchange=e=>{basis=e.target.value;unit=0;sync();drawAll()};$('#synUnit').onchange=e=>{unit=+e.target.value;sync();drawAll()};$('#diffToggle').onchange=e=>{diff=e.target.checked;drawView()};$$('[data-remove]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(cols.length<=2)return;cols=cols.filter(x=>x!==b.dataset.remove);sync();drawAll()});$$('[data-add]').forEach(b=>b.onclick=()=>{cols.push(b.dataset.add);sync();drawAll()});
   let drag=null;$$('.drag-wit').forEach(b=>{b.ondragstart=()=>{drag=b.dataset.w;b.classList.add('dragging')};b.ondragend=()=>b.classList.remove('dragging');b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();const target=b.dataset.w;if(!drag||drag===target)return;const a=cols.indexOf(drag),t=cols.indexOf(target);cols.splice(a,1);cols.splice(t,0,drag);sync();drawAll()}})
 }
 function drawSummary(){const u=rows()[unit];$('#synSummary').innerHTML=`<div class="syn-locus"><div><span class="kicker">Organized by ${esc(witnessLabel(basis))}</span><h2>${esc(romanLabel(u))}</h2></div><div class="locus-links">${cols.map(w=>witnessPill(w,w)).join('')}</div></div>`}
 function drawView(){const u=rows()[unit];if(!u)return;const visible=cols.map(w=>u.witnesses[w]),base=visible[0]?.text||'',alignments=visible.slice(1).map(x=>alignWords(base,x.text));const refHtml=diff?renderReference(base,alignments):markupText(base,'',true);$('#syn').innerHTML=`<div class="syn-viewport-note">${cols.length>3?'Scroll horizontally inside the synopsis to keep the page frame fixed.':'Columns fit the available page width.'}</div><div class="syn-grid ${cols.length<=3?'syn-fit':'syn-scroll'}" style="--cols:${cols.length}">${cols.map((w,ix)=>{const x=u.witnesses[w],own=x.sections||[];let tx;if(ix===0)tx=refHtml;else tx=diff?renderDiffOps(alignments[ix-1]):markupText(x.text,'',true);return `<article class="syn-col" ${cssVar(w)}><header><div>${witnessPill(w,w)}<span class="reference-tag">${ix===0?'reference':''}</span></div><div class="own-units">${own.length?own.map(s=>`<span>${esc(s.label)}</span>`).join(''):'<span>—</span>'}</div></header><div class="structure-ticks">${own.map((s,j)=>`<i style="left:${j/Math.max(1,own.length)*100}%"></i>`).join('')}</div><div class="syn-text">${tx.replace(/\n/g,'<br>')}</div><footer>${routeLink('edition',{wit:w,unit:own[0]?.index||0},'Open this witness →','link-arrow')}<a href="${D.teiDownloads[w]}" download>TEI ↓</a></footer></article>`}).join('')}</div>`}
 function drawAll(){if(unit<0||unit>=rows().length)unit=0;drawControls();drawSummary();drawView()}
 drawAll();
}

// ---------- WITNESSES / TRADITION ----------
function witnesses(){setTimeout(()=>{setupMap();setupRibbon()},0);return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Textual tradition</div><h1>Witnesses & transmission</h1></div></div><div class="tradition-grid"><div class="card"><div class="kicker">Transmission</div><h2>Open tradition, not a simple tree</h2>${liveMap(false)}</div><div class="card"><div class="kicker">Organization</div><h2>Boundaries are part of the evidence</h2><p class="muted">Use a boundary to move directly into a synopsis organized by that witness.</p>${structuralRibbon()}</div></div><div class="wgrid-v7">${witnessCards()}</div><div class="card similarity-card"><div class="kicker">Textual proximity</div><h2>Witness similarity across a common 22-part projection</h2>${similarityMatrix()}</div></div>`}
function similarityMatrix(){const rows=WITS.map(a=>`<tr><th>${witnessPill(a,a)}</th>${WITS.map(b=>{const v=D.witnessSimilarity[a][b];return `<td style="--sim:${v}" title="${(v*100).toFixed(1)}%">${(v*100).toFixed(1)}</td>`}).join('')}</tr>`).join('');return `<div class="table-scroll"><table class="sim-matrix"><thead><tr><th></th>${WITS.map(w=>`<th>${w}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`}

// ---------- SEARCH ----------
function searchPage(){setTimeout(setupSearch,0);return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Search across layers</div><h1>Search</h1><p>Search witness text, named entities, and controlled concepts. Results retain witness and structural context.</p></div></div><div class="search-box card"><input id="searchInput" type="search" placeholder="Search Russian text or an indexed name…"><select id="searchWit"><option value="all">All texts</option>${ALL.map(w=>`<option value="${w}">${esc(witnessLabel(w))}</option>`).join('')}</select><button id="searchBtn" class="btn btn-primary">Search</button></div><div id="searchSummary" class="result-summary"></div><div id="results" class="results-v7"></div></div>`}
function setupSearch(){const R=parseRoute(),inp=$('#searchInput');inp.value=R.p.get('q')||'';$('#searchWit').value=R.p.get('wit')||'all';function run(){const q=inp.value.trim(),nw=norm(q),wf=$('#searchWit').value;if(q.length<2){$('#results').innerHTML='<div class="notice">Enter at least two characters.</div>';return}const res=[];for(const w of ALL){if(wf!=='all'&&wf!==w)continue;const segs=w==='reconstructed'?D.reconstructed:D.witnesses[w];for(const s of segs){if(norm(s.text).includes(nw)){const low=s.text.toLowerCase(),ix=low.indexOf(q.toLowerCase()),snippet=s.text.slice(Math.max(0,ix-150),Math.min(s.text.length,ix+q.length+220));res.push({kind:'text',w,s,snippet})}}}for(const [typ,arr] of Object.entries(D.entities))for(const e of arr)if(norm(e.label).includes(nw)||(e.forms||[]).some(f=>norm(f).includes(nw)))res.push({kind:'entity',typ,e});for(const c of D.conceptIndex.concepts)if(norm(c.label).includes(nw))res.push({kind:'concept',c});history.replaceState(null,'',`#search?q=${encodeURIComponent(q)}&wit=${wf}`);$('#searchSummary').textContent=`${res.length} results`;$('#results').innerHTML=res.slice(0,300).map(r=>r.kind==='entity'?`<article class="result-card"><div class="result-type">${TYPE_LABEL[r.typ]}</div><h3>${routeLink('entities',{entity:r.e.id},esc(r.e.label))}</h3><p>${esc((r.e.forms||[]).join(' · '))}</p></article>`:r.kind==='concept'?`<article class="result-card"><div class="result-type">Concept</div><h3>${routeLink('distant',{concept:r.c.id},esc(r.c.label))}</h3></article>`:`<article class="result-card"><div class="result-top">${witnessPill(r.w)}<span>${esc(romanLabel(r.s))}</span></div><p>${markupText(r.snippet,q,true)}</p>${routeLink('edition',{wit:r.w,unit:r.s.index,q},'Open occurrence →','link-arrow')}</article>`).join('')||'<div class="notice">No results.</div>'}$('#searchBtn').onclick=run;inp.onkeydown=e=>{if(e.key==='Enter')run()};if(inp.value)run()}

// ---------- ENTITY INDEX ----------
function entitiesPage(){setTimeout(setupEntities,0);return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Named-entity index</div><h1>People, places, organizations & works</h1><p>The index is generated by a fresh corpus-wide NER pass across all reconstructed witnesses and is linked back to every occurrence.</p></div><div class="page-actions"><a class="btn btn-quiet" href="${D.teiDownloads.ner}" download>NER TEI ledger ↓</a></div></div><div class="entity-layout-v7"><aside class="entity-sidebar card"><input id="entityFilter" placeholder="Filter entities…"><div class="entity-type-tabs"><button data-type="all" class="active">All</button>${Object.keys(D.entities).map(t=>`<button data-type="${t}">${TYPE_LABEL[t]}s</button>`).join('')}</div><div id="entityList"></div></aside><section id="entityMain"></section></div></div>`}
function setupEntities(){const R=parseRoute();let chosen=R.p.get('entity')||null,type='all';const list=[];Object.entries(D.entities).forEach(([typ,arr])=>arr.forEach(e=>list.push({typ,e})));function renderList(filter=''){const n=norm(filter);$('#entityList').innerHTML=list.filter(x=>(type==='all'||x.typ===type)&&(!n||norm(x.e.label+' '+(x.e.forms||[]).join(' ')).includes(n))).map(x=>`<button data-e="${x.e.id}" class="entity-list-row ${chosen===x.e.id?'active':''}"><span><i class="type-dot ${x.typ}"></i>${esc(x.e.label)}</span><small>${TYPE_LABEL[x.typ]}</small></button>`).join('');$$('[data-e]').forEach(b=>b.onclick=()=>{chosen=b.dataset.e;history.replaceState(null,'',`#entities?entity=${chosen}`);renderList($('#entityFilter').value);renderMain()})}function renderMain(){if(!chosen){renderOverview();return}const x=entityById(chosen);if(!x){renderOverview();return}const {typ,e}=x,occ=D.nerIndex.occurrences.filter(o=>o.entity===e.id),freq=ALL.map(w=>[w,D.nerIndex.frequency[w]?.[e.id]||0]),max=Math.max(1,...freq.map(x=>x[1]));const neigh=[];for(const [k,v] of Object.entries(D.knowledgeGraph.pairs||{})){const [a,b]=k.split('|');if(a===e.id||b===e.id){const other=a===e.id?b:a,oe=entityById(other);if(oe)neigh.push([oe.e,v])}}neigh.sort((a,b)=>b[1]-a[1]);$('#entityMain').innerHTML=`<div class="entity-profile card"><div class="result-type">${TYPE_LABEL[typ]}</div><h2>${esc(e.label)}</h2><div class="surface-forms">${(e.forms||[]).map(f=>`<span>${esc(f)}</span>`).join('')}</div>${e.note?`<p class="muted">${esc(e.note)}</p>`:''}<h3>Distribution by witness</h3><div class="bars-v7">${freq.map(([w,c])=>`<button onclick="go('search',{q:'${encodeURIComponent(e.forms?.[0]||e.label)}',wit:'${w}'})"><span>${witnessPill(w,w)}</span><i style="width:${Math.max(2,c/max*100)}%"></i><b>${c}</b></button>`).join('')}</div><h3>Co-occurring entities</h3><div class="chips">${neigh.slice(0,18).map(([n,c])=>routeLink('entities',{entity:n.id},`${esc(n.label)} <small>${c}</small>`,'chip')).join('')||'<span class="muted">No close co-occurrences.</span>'}</div>${typ==='places'&&e.lat!==undefined?`<div class="entity-map-link">${routeLink('distant',{view:'geo',place:e.id},'Locate in spatial view →','link-arrow')}</div>`:''}</div><div class="occurrences card"><div class="card-head"><h3>Occurrences</h3><span>${occ.length}</span></div>${occ.slice(0,250).map(o=>`<article><div class="result-top">${witnessPill(o.witness,o.witness)}<span>${esc(o.unit_label)}</span></div><p>…${markupText(o.snippet,o.form,true)}…</p>${routeLink('edition',{wit:o.witness,unit:o.unit_index,q:o.form},'Open in context →','link-arrow')}</article>`).join('')}</div>`}function renderOverview(){const top=D.nerIndex.matrix.slice().sort((a,b)=>Object.values(b.counts).reduce((x,y)=>x+y,0)-Object.values(a.counts).reduce((x,y)=>x+y,0)).slice(0,28),mx=Math.max(...top.map(x=>Object.values(x.counts).reduce((a,b)=>a+b,0)),1);$('#entityMain').innerHTML=`<div class="card"><div class="kicker">NER overview</div><h2>${D.nerMeta.occurrences} mentions across six text views</h2><p class="muted">${esc(D.nerMeta.method)}</p><div class="ner-stats">${Object.entries(D.nerMeta.entity_counts).map(([k,v])=>`<div><b>${v}</b><span>${TYPE_LABEL[k]} authorities</span></div>`).join('')}</div></div><div class="card"><h3>Most frequent entities</h3><div class="rank-bars-v7">${top.map(x=>{const n=Object.values(x.counts).reduce((a,b)=>a+b,0);return `<button data-open="${x.id}"><span>${esc(x.label)}</span><i style="width:${n/mx*100}%"></i><b>${n}</b></button>`}).join('')}</div></div>`;$$('[data-open]').forEach(b=>b.onclick=()=>{chosen=b.dataset.open;history.replaceState(null,'',`#entities?entity=${chosen}`);renderList();renderMain()})}$('#entityFilter').oninput=e=>renderList(e.target.value);$$('.entity-type-tabs button').forEach(b=>b.onclick=()=>{type=b.dataset.type;$$('.entity-type-tabs button').forEach(x=>x.classList.toggle('active',x===b));renderList($('#entityFilter').value)});renderList();renderMain()}

// ---------- DISTANT READING ----------
function distant(){setTimeout(setupDistant,0);return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Distant reading</div><h1>Patterns across witnesses</h1><p>Every visualization is an entry point back into the edition. The goal is to expose difference, distribution, and association without replacing close reading.</p></div></div><div class="distant-tabs"><button data-view="overview" class="active">Overview</button><button data-view="atlas">Entity atlas</button><button data-view="diff">Witness differences</button><button data-view="geo">Geography</button><button data-view="network">Knowledge network</button></div><div id="distantMain"></div></div>`}
function setupDistant(){const R=parseRoute();let view=R.p.get('view')||'overview';$$('.distant-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));function setView(v){view=v;$$('.distant-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));history.replaceState(null,'',`#distant?view=${v}`);render()}function render(){if(view==='atlas')renderAtlas();else if(view==='geo')renderGeo();else if(view==='network')renderNetwork();else if(view==='diff')renderDiff();else renderOverview()}$$('.distant-tabs button').forEach(b=>b.onclick=()=>setView(b.dataset.view));function renderAtlas(){$('#distantMain').innerHTML=`<div class="card atlas-card"><div class="card-head"><div><div class="kicker">Entity atlas</div><h2>A map of named knowledge across the witnesses</h2><p class="muted">The horizontal axis is a weighted profile across K, A1, B, A2, and N; vertical bands separate entity types. This is an exploratory map, not a stemma.</p></div><span class="muted">Select an entity to open all occurrences</span></div>${entityAtlas(false)}</div>`}function renderOverview(){const types=Object.keys(D.entities);$('#distantMain').innerHTML=`<div class="distant-grid"><div class="card"><div class="kicker">Named entities</div><h2>Mentions by witness</h2><div class="witness-total-bars">${ALL.map(w=>{const n=D.nerMeta.by_witness[w]||0;return `<button onclick="go('entities',{})">${witnessPill(w,w)}<i style="width:${n/Math.max(...Object.values(D.nerMeta.by_witness))*100}%"></i><b>${n}</b></button>`}).join('')}</div></div><div class="card"><div class="kicker">Concept profile</div><h2>Top indexed concepts</h2>${conceptOverview()}</div></div><div class="card wide"><div class="kicker">Textual similarity</div><h2>Witness-to-witness proximity</h2>${similarityMatrix()}</div></div><div class="card wide"><div class="kicker">Variation landscape</div><h2>Where the tradition changes most</h2>${varianceLandscape()}</div></div></div>`;setTimeout(setupVariance,0)}function conceptOverview(){const totals=D.conceptIndex.concepts.map(c=>[c,D.conceptIndex.frequency.reconstructed[c.id]||0]).sort((a,b)=>b[1]-a[1]).slice(0,12),max=Math.max(...totals.map(x=>x[1]),1);return `<div class="concept-bars">${totals.map(([c,n])=>`<button onclick="go('distant',{view:'diff'})"><span>${esc(c.label)}</span><i style="width:${n/max*100}%"></i><b>${n}</b></button>`).join('')}</div>`}function renderDiff(){const rows=D.nerIndex.matrix.filter(x=>x.spread>0).slice(0,30);const max=Math.max(...rows.flatMap(x=>Object.values(x.counts)),1);$('#distantMain').innerHTML=`<div class="card"><div class="card-head"><div><div class="kicker">Entity fingerprints</div><h2>Which named entities distinguish witnesses?</h2></div><span class="muted">Sorted by cross-witness spread</span></div><div class="heat-table"><div class="heat-row head"><span>Entity</span>${WITS.map(w=>`<b>${w}</b>`).join('')}</div>${rows.map(r=>`<button class="heat-row" onclick="go('entities',{entity:'${r.id}'})"><span>${esc(r.label)}</span>${WITS.map(w=>`<i style="--h:${(r.counts[w]||0)/max}" title="${w}: ${r.counts[w]||0}">${r.counts[w]||''}</i>`).join('')}</button>`).join('')}</div></div><div class="card"><div class="kicker">Concept fingerprints</div><h2>Controlled concepts by witness</h2>${conceptHeatmap()}</div>`}function conceptHeatmap(){const cs=D.conceptIndex.concepts,max=Math.max(...WITS.flatMap(w=>cs.map(c=>D.conceptIndex.frequency[w][c.id]||0)),1);return `<div class="heat-table concepts"><div class="heat-row head"><span>Concept</span>${WITS.map(w=>`<b>${w}</b>`).join('')}</div>${cs.map(c=>`<div class="heat-row"><span>${esc(c.label)}</span>${WITS.map(w=>{const n=D.conceptIndex.frequency[w][c.id]||0;return `<i style="--h:${n/max}" title="${w}: ${n}">${n||''}</i>`}).join('')}</div>`).join('')}</div>`}function renderGeo(){const places=D.entities.places.filter(p=>p.lat!==undefined),counts={};places.forEach(p=>counts[p.id]=ALL.reduce((s,w)=>s+(D.nerIndex.frequency[w]?.[p.id]||0),0));const max=Math.max(...Object.values(counts),1);const x=lon=>(lon+15)/(125+15)*900,y=lat=>(72-lat)/(72-24)*470;$('#distantMain').innerHTML=`<div class="card geo-card"><div class="card-head"><div><div class="kicker">Spatial index</div><h2>Places named across the witnesses</h2></div><span class="muted">Circle size = corpus mentions</span></div><svg class="geo-map" viewBox="0 0 900 470">${[-10,10,30,50,70,90,110].map(l=>`<line x1="${x(l)}" y1="0" x2="${x(l)}" y2="470"/>`).join('')}${[30,40,50,60,70].map(l=>`<line x1="0" y1="${y(l)}" x2="900" y2="${y(l)}"/>`).join('')}${places.map(p=>{const n=counts[p.id],r=5+12*Math.sqrt(n/max);return `<g class="place-dot" data-place="${p.id}" tabindex="0"><circle cx="${x(p.lon)}" cy="${y(p.lat)}" r="${r}"/><text x="${x(p.lon)+r+5}" y="${y(p.lat)+4}">${esc(p.label)}</text><title>${esc(p.label)}: ${n} mentions</title></g>`}).join('')}</svg></div><div class="card"><div class="kicker">Place × witness</div><h2>Geographic differences</h2><div class="place-list">${places.sort((a,b)=>counts[b.id]-counts[a.id]).map(p=>`<button data-place="${p.id}"><span>${esc(p.label)}</span><div>${WITS.map(w=>{const n=D.nerIndex.frequency[w]?.[p.id]||0;return `<i ${cssVar(w)} title="${w}: ${n}" style="height:${4+Math.min(36,n*4)}px"></i>`}).join('')}</div><b>${counts[p.id]}</b></button>`).join('')}</div></div>`;$$('[data-place]').forEach(b=>b.onclick=()=>go('entities',{entity:b.dataset.place}))}function renderNetwork(){const pairs=Object.entries(D.knowledgeGraph.pairs).sort((a,b)=>b[1]-a[1]).slice(0,50);const degree=CounterJS(pairs.flatMap(([k,v])=>k.split('|').flatMap(id=>Array(Math.min(v,5)).fill(id))));const ids=Object.entries(degree).sort((a,b)=>b[1]-a[1]).slice(0,28).map(x=>x[0]),idset=new Set(ids),edges=pairs.filter(([k])=>k.split('|').every(x=>idset.has(x))).slice(0,38);const cx=430,cy=285,R=215,pos={};ids.forEach((id,i)=>{const a=-Math.PI/2+i*2*Math.PI/ids.length;pos[id]=[cx+Math.cos(a)*R,cy+Math.sin(a)*R]});const maxd=Math.max(...Object.values(degree),1);$('#distantMain').innerHTML=`<div class="card network-card"><div class="card-head"><div><div class="kicker">Co-occurrence network</div><h2>Named entities that appear near one another</h2></div><span class="muted">2-sentence windows; select a node to open its index</span></div><svg class="knowledge-net" viewBox="0 0 860 570">${edges.map(([k,v])=>{const [a,b]=k.split('|'),A=pos[a],B=pos[b];return `<line x1="${A[0]}" y1="${A[1]}" x2="${B[0]}" y2="${B[1]}" style="--w:${Math.min(1,v/6)}" data-a="${a}" data-b="${b}"/>`}).join('')}${ids.map(id=>{const p=pos[id],x=entityById(id),r=9+12*(degree[id]/maxd);return `<g class="kn-node ${x?.typ||''}" data-e="${id}" tabindex="0"><circle cx="${p[0]}" cy="${p[1]}" r="${r}"/><text x="${p[0]}" y="${p[1]+r+14}">${esc(x?.e.label||id)}</text></g>`}).join('')}</svg><div id="netInfo" class="network-info muted">Hover a node to isolate its immediate network.</div></div>`;$$('.kn-node').forEach(n=>{n.onclick=()=>go('entities',{entity:n.dataset.e});n.onmouseenter=()=>{const id=n.dataset.e;$$('.knowledge-net line').forEach(l=>l.classList.toggle('hot',l.dataset.a===id||l.dataset.b===id));$$('.kn-node').forEach(x=>x.classList.toggle('dim',x.dataset.e!==id&&!edges.some(([k])=>{const [a,b]=k.split('|');return (a===id&&b===x.dataset.e)||(b===id&&a===x.dataset.e)})));$('#netInfo').textContent=entityById(id)?.e.label||id};n.onmouseleave=()=>{$$('.knowledge-net line').forEach(l=>l.classList.remove('hot'));$$('.kn-node').forEach(x=>x.classList.remove('dim'))}})}render();}

// ---------- METHOD ----------
function method(){return `<div class="page-shell"><div class="page-title"><div><div class="kicker">Documentation</div><h1>Editorial method & data layers</h1></div></div><div class="method-grid"><div class="card"><h2>Close and distant reading share one corpus</h2><p>Each witness preserves its own protocol structure. The synopsis projects witnesses into a chosen organizing structure without renumbering the other witnesses. The reader exposes internal blocks and cross-witness boundaries rather than presenting each protocol as an undifferentiated wall of text.</p><p>The release 1.1 NER layer (pipeline v7) was rerun across every witness reconstruction using an expanded scholarly authority list and longest-surface matching. Named entities and thematic concepts are kept as separate analytical layers.</p></div><div class="card"><h2>TEI downloads</h2><div class="download-grid">${Object.entries(D.teiDownloads).map(([k,v])=>`<a href="${v}" download><span>${esc(k)}</span><b>↓</b></a>`).join('')}</div></div><div class="card"><h2>Visualization principles</h2><p>Variant intensity is used as navigation, not as a verdict about textual value. Witness colors encode identity consistently; variant colors encode operation type. Structural boundaries are shown independently from both.</p><p>Named-entity maps and co-occurrence graphs always link back to occurrences in the witnesses.</p></div><div class="card"><h2>Source anomalies</h2><p>Printed apparatus notes 380 and 2502 remain explicitly marked as unresolved source anomalies rather than silently supplied.</p></div></div>`}


// ---------- contextual research guide ----------
const GUIDE_PAGES={
  home:{title:'Project map',lead:'The home page is the orientation layer. Use it to enter the edition through textual transmission, structural variation, entities, or individual witnesses.',tips:[
    ['Transmission map','Hover over a node to trace relationships. Select a surviving witness to read it; select a hypothetical stage to compare its descendants.'],
    ['Variation landscape','Darker cells mark loci with more variation. Select a protocol to open that locus in the synopsis.'],
    ['Competing structures','The 22 / 27 / 24 ribbons show that witnesses divide the same textual continuum differently. Select any segment to enter the comparison from that witness structure.'],
    ['Entity atlas','Use the distant-reading map to see which people, places, organizations, and works cluster in different witnesses. Every node returns to occurrences in the text.']
  ]},
  edition:{title:'Close reading',lead:'Read one witness at a time while keeping its own internal structure, apparatus, entity links, and the boundaries of other witnesses visible.',tips:[
    ['Choose a text','Switch between the reconstructed text and K, A1, A2, N, or B. The navigation list changes with the structure of the selected witness.'],
    ['Protocol anatomy','The strip above the text maps internal blocks. Select a block to jump to it and inspect its variation, concepts, entities, and cross-witness boundaries.'],
    ['Inspector','Use Anatomy for structure, Apparatus for textual operations, and Entities for named references in the current unit.'],
    ['Compare or download','“Compare this locus” opens the same passage in the synopsis. The TEI button downloads the selected encoded text.']
  ]},
  synopsis:{title:'Comparative synopsis',lead:'The synopsis separates two decisions: which witness supplies the organizing structure, and which witnesses are displayed for comparison.',tips:[
    ['Organizing structure','Choose K, A1, A2, N, B, or the reconstruction as the structural basis. Rows follow that text’s divisions rather than forcing all witnesses into one numbering system.'],
    ['Add, remove, reorder','Use the witness controls to decide which columns are visible. Reorder witnesses so that the first visible column becomes the textual reference for highlighting.'],
    ['Read the colors','Added text, substitutions, and gaps use different visual treatments. Witness identity has its own persistent color and is never encoded by variant color alone.'],
    ['Stay aligned','With many witnesses, horizontal scrolling is contained inside the synopsis so the page frame remains fixed.']
  ]},
  witnesses:{title:'Textual tradition',lead:'This page explains the surviving witnesses, hypothetical stages, relationships, and the competing 22 / 27 / 24 organizations.',tips:[
    ['Witness cards','Open a witness directly for close reading or send it to the comparative view.'],
    ['Transmission','The map represents the editorial reconstruction of descent and contamination; it is not a simple genealogical tree.'],
    ['Structure','Use the structural comparison to see where witnesses place protocol boundaries differently.']
  ]},
  search:{title:'Search',lead:'Search across the reconstructed edition and all five witness reconstructions without losing the path back to the textual context.',tips:[
    ['Scope','Restrict the search to a witness when you want to test the distribution of a reading or name.'],
    ['Results','Each result opens the exact witness and unit, with the query highlighted in context.'],
    ['Entities','For named people, places, organizations, or works, the Index provides a more structured path than plain text search.']
  ]},
  entities:{title:'Entity index',lead:'The index connects named entities to every encoded occurrence, their witness distribution, and nearby entities.',tips:[
    ['Filter','Browse by entity type or search the authority forms used by the NER layer.'],
    ['Distribution','Bars show how often an entity appears in each witness.'],
    ['Occurrences','Open any occurrence to return to the exact protocol and witness.'],
    ['Distant reading','Places link to the geographic view; co-occurring entities connect the index to the knowledge network.']
  ]},
  distant:{title:'Distant reading',lead:'These visualizations are navigational views of the same encoded corpus. They are designed to expose distribution and difference, then return you to close reading.',tips:[
    ['Entity atlas','Maps entities by their weighted witness profile and entity type. Node size reflects total mentions.'],
    ['Witness differences','Entity and concept fingerprints show which indexed features vary most across witnesses.'],
    ['Geography','The spatial view maps indexed places and compares their frequency across witnesses.'],
    ['Knowledge network','Edges represent close co-occurrence in two-sentence windows. Select a node to inspect all occurrences.']
  ]},
  method:{title:'Method and TEI',lead:'This page documents the editorial model, analytical layers, unresolved source anomalies, and TEI downloads.',tips:[
    ['TEI','Download the complete package or individual witness encodings.'],
    ['Editorial model','The reconstructed text, witness texts, apparatus, named entities, and structural relations are encoded as distinct but linked layers.'],
    ['Limits','Source anomalies remain marked rather than silently normalized or supplied.']
  ]}
};
const GUIDE_OVERVIEW=[
  ['Read','Close reading of one witness, with its own protocol structure and internal anatomy.','#edition'],
  ['Compare','A configurable synopsis: choose the organizing structure, visible witnesses, and their order.','#synopsis'],
  ['Tradition','Witness descriptions, the transmission map, and the 22 / 27 / 24 structural problem.','#witnesses'],
  ['Search','Full-text search across the reconstruction and witness texts.','#search'],
  ['Index','People, places, organizations, and works, linked to all occurrences.','#entities'],
  ['Distant','Entity atlas, witness fingerprints, geography, co-occurrence, and variation landscape.','#distant'],
  ['Method','Editorial principles and one-click TEI downloads.','#method']
];
function guideMarkup(page){
  const g=GUIDE_PAGES[page]||GUIDE_PAGES.home;
  return `<div class="guide-current"><div class="guide-page-tag">On this page</div><h3>${esc(g.title)}</h3><p>${esc(g.lead)}</p><div class="guide-tips">${g.tips.map(([h,t],i)=>`<div class="guide-tip"><span>${i+1}</span><div><b>${esc(h)}</b><p>${esc(t)}</p></div></div>`).join('')}</div></div><div class="guide-overview"><div class="guide-page-tag">Edition map</div><h3>What is here?</h3><p>All views are linked. You can enter through a witness, a variant locus, a person or place, or a distant-reading visualization and move back to the underlying text.</p><div class="guide-route-grid">${GUIDE_OVERVIEW.map(([h,t,href])=>`<a href="${href}" class="guide-route"><b>${esc(h)}</b><span>${esc(t)}</span></a>`).join('')}</div><div class="guide-note"><b>Experimental · internal</b><span>This is a working scholarly reconstruction for research review. The TEI is the encoded source layer; the interface is a navigational projection of it.</span></div></div>`
}
function openGuide(){const ov=$('#guideOverlay'),body=$('#guideBody');if(!ov||!body)return;body.innerHTML=guideMarkup(parseRoute().page);ov.classList.add('open');ov.setAttribute('aria-hidden','false');document.documentElement.classList.add('guide-open');setTimeout(()=>$('#guideClose')?.focus(),0)}
function closeGuide(){const ov=$('#guideOverlay');if(!ov)return;ov.classList.remove('open');ov.setAttribute('aria-hidden','true');document.documentElement.classList.remove('guide-open');$('#guideButton')?.focus()}
function setupGuide(){const btn=$('#guideButton'),ov=$('#guideOverlay');if(!btn||!ov)return;btn.onclick=openGuide;$('#guideClose').onclick=closeGuide;ov.addEventListener('click',e=>{if(e.target===ov)closeGuide()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ov.classList.contains('open'))closeGuide()});}

// ---------- render ----------
function render(){const R=parseRoute();if($('#guideOverlay')?.classList.contains('open'))$('#guideBody').innerHTML=guideMarkup(R.page);const f={home,edition,synopsis,witnesses,search:searchPage,entities:entitiesPage,distant,method}[R.page]||home;$$('.nav-v7 a[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===R.page));$('#main').innerHTML=f()}
window.addEventListener('hashchange',render);window.addEventListener('DOMContentLoaded',()=>{render();setupGuide()});
